import{_ as o,o as a,c as l,a2 as i}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"4.4 兆欧表","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-4-zhao-ou-biao.md","filePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-4-zhao-ou-biao.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-4-zhao-ou-biao.md"};function n(e,t,s,g,h,d){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_4-4-兆欧表" tabindex="-1">4.4 兆欧表 <a class="header-anchor" href="#_4-4-兆欧表" aria-label="Permalink to &quot;4.4 兆欧表&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>兆欧表又叫<strong>绝缘电阻表</strong>、俗称&quot;摇表&quot;,是检查设备绝缘是否完好的专用仪表——测的是几兆欧到几千兆欧的大电阻。绝缘电阻好不好,直接关系到会不会漏电、触电,所以这是电工最常用也最强调安全的仪表之一。</p><h2 id="一、兆欧表是干什么的" tabindex="-1">一、兆欧表是干什么的 <a class="header-anchor" href="#一、兆欧表是干什么的" aria-label="Permalink to &quot;一、兆欧表是干什么的&quot;">​</a></h2><p><strong>测量绝缘电阻</strong>:设备(电动机、电缆、配电柜)的绝缘材料老化、受潮、破损后,绝缘电阻会下降,可能造成漏电甚至触电事故。兆欧表就是给绝缘&quot;体检&quot;的。</p><ul><li>量程很大,单位是<strong>兆欧(MΩ)</strong>;</li><li>测量时仪表自己<strong>产生一个直流高压</strong>(常用 500 V、1000 V、2500 V),施加在绝缘体上测漏电流,从而算出绝缘电阻;</li><li><strong>绝缘电阻越大,绝缘越好</strong>。</li></ul><blockquote><p>💡 为什么叫&quot;摇表&quot;?老式兆欧表靠<strong>手摇发电机</strong>产生高压,测量时要&quot;摇&quot;,所以俗称摇表。现代也有电子式的。</p></blockquote><h2 id="二、怎么选兆欧表" tabindex="-1">二、怎么选兆欧表 <a class="header-anchor" href="#二、怎么选兆欧表" aria-label="Permalink to &quot;二、怎么选兆欧表&quot;">​</a></h2><p><strong>按被测设备电压选额定电压等级</strong>:</p><table tabindex="0"><thead><tr><th>被测设备</th><th>选用兆欧表电压</th></tr></thead><tbody><tr><td>低压电气设备(1 kV 以下)</td><td><strong>500 V</strong>(常用)</td></tr><tr><td>高压设备(1 kV 及以上)</td><td>1000 V、2500 V 等</td></tr></tbody></table><blockquote><p>⚠️ 用电压等级过高的兆欧表测低压设备,可能<strong>击穿</strong>设备的绝缘,反而损坏设备。</p></blockquote><h2 id="三、测量步骤-必背流程" tabindex="-1">三、测量步骤(必背流程) <a class="header-anchor" href="#三、测量步骤-必背流程" aria-label="Permalink to &quot;三、测量步骤(必背流程)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>断电 → 验电 → 放电 → 接表 → 摇测 → 读数 → 放电</span></span></code></pre></div><ol><li><strong>断电</strong>:断开被测设备电源,保证无电;</li><li><strong>验电</strong>:用验电器确认设备无电;</li><li><strong>放电</strong>:对电缆、电容等,测量前先将残余电荷<strong>放电</strong>(用放电棒或短路放电);</li><li><strong>接线</strong>:兆欧表有 L(线路)、E(接地)、G(屏蔽)三个接线柱: <ul><li><strong>L 接被测设备的导电部分</strong>;</li><li><strong>E 接设备的金属外壳(接地部分)</strong>;</li><li>G 屏蔽线用于有泄漏电流的场合(电缆测量);</li></ul></li><li><strong>摇测</strong>: <ul><li>将兆欧表放在水平位置,先摇到额定转速,<strong>再接入 L 线</strong>;</li><li>转速保持 <strong>约 120 r/min</strong>,匀速摇测约 1 分钟;</li><li>待指针稳定后读数;</li></ul></li><li><strong>读数后放电</strong>:测量完毕,先取下 L 线,再对被测设备<strong>放电</strong>,才能拆除。</li></ol><h2 id="四、安全注意事项" tabindex="-1">四、安全注意事项 <a class="header-anchor" href="#四、安全注意事项" aria-label="Permalink to &quot;四、安全注意事项&quot;">​</a></h2><ul><li>严禁在<strong>带电设备</strong>上测量;</li><li>测量时<strong>人体不得接触被测设备的导电部分</strong>(兆欧表输出电压可能达数百伏);</li><li>测电缆、电容前<strong>必须放电</strong>,防止残余电荷伤人;</li><li>兆欧表摇测时不要接触表笔的金属部分。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 测低压设备绝缘用 <strong>500 V</strong> 兆欧表。</li><li>✅ 转速 <strong>约 120 r/min</strong>,摇测到指针稳定。</li><li>✅ 测量前必须:断电 → 验电 → <strong>放电</strong>。</li><li>✅ 接线:L 接导电部分,E 接外壳。</li><li>⚠️ 易混点:兆欧表(测绝缘电阻,MΩ)≠万用表欧姆挡(测小电阻,Ω)。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>兆欧表测绝缘电阻,单位 MΩ,绝缘电阻越大越好。</li><li>低压设备用 500 V 档;测量流程:断电→验电→放电→摇测→放电。</li><li>测电缆、电容必须先放电,这是防触电的关键。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)测量低压电气设备绝缘电阻,应选用()兆欧表。 A. 100 V　B. 500 V　C. 2500 V　D. 任意电压</li><li>(判断)兆欧表摇测时,转速应保持在约 120 r/min。( )</li><li>(判断)测量电缆绝缘电阻前,应对电缆进行放电。( )</li><li>(单选)兆欧表的 L 接线柱应接()。 A. 设备金属外壳　B. 设备导电部分　C. 大地　D. 零线</li><li>(判断)兆欧表可以测量带电设备的绝缘电阻。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。低压(1 kV 以下)设备用 500 V 兆欧表。</li><li><strong>√</strong>。约 120 r/min,匀速摇测。</li><li><strong>√</strong>。电缆电容存有残余电荷,必须先放电。</li><li><strong>B</strong>。L 接导电部分,E 接外壳(接地部分)。</li><li><strong>×</strong>。严禁在带电设备上测量。</li></ol></details>',23)])])}const b=o(r,[["render",n]]);export{u as __pageData,b as default};
